import json, re, pathlib

d = pathlib.Path("deliverable")

# 1. JSON parse + internal reconciliation
j = json.loads((d/"year1_comparison.json").read_text())
print("JSON parses OK; options:", list(j.get("options", j).keys()) if isinstance(j, dict) else "?")

def find_options(obj):
    if isinstance(obj, dict):
        if all(k in obj for k in ("entity_tax","founder_tax","payroll_taxes")) or "total" in obj:
            pass
        for v in obj.values():
            yield from find_options(v)
    elif isinstance(obj, list):
        for v in obj: yield from find_options(v)

# generic check: any dict with entity_tax, founder_tax, payroll_taxes, total
def check(obj, path=""):
    ok = True
    if isinstance(obj, dict):
        keys = set(obj)
        if {"entity_tax","founder_tax","payroll_taxes","total"} <= keys or ({"entity_tax","total"} <= keys):
            try:
                s = obj["entity_tax"]+obj["founder_tax"]+obj["payroll_taxes"]
                t = obj["total"]
                if abs(s-t) > 0.01:
                    print(f"MISMATCH at {path}: {s} != {t}"); ok=False
                else:
                    print(f"OK {path}: {s:,.2f} == total {t:,.2f}")
            except Exception as e:
                print("skip", path, e)
        for k,v in obj.items():
            ok &= check(v, f"{path}/{k}")
    elif isinstance(obj, list):
        for i,v in enumerate(obj): ok &= check(v, f"{path}[{i}]")
    return ok
check(j)

# 2. Citation check: every library filename referenced in deliverables must exist in INDEX.md
idx = pathlib.Path("library/INDEX.md").read_text()
files = set(re.findall(r'`([A-Za-z0-9_\-\.]+\.md)`', idx)) | set(re.findall(r'([A-Za-z0-9_\-]+\.md)', idx))
print("\nINDEX files:", sorted(files))
bad = []
for f in d.glob("*"):
    if f.suffix not in (".md",".json"): continue
    txt = f.read_text()
    for m in re.findall(r'`([a-z0-9_\-]+\.md)`', txt):
        if m not in files and m not in ("recommendation.md","term_sheet.md","compliance_calendar.md","year1_comparison.json","QUESTIONS.md","STATUS.md","INDEX.md"):
            bad.append((f.name, m))
    for m in re.findall(r'library:\s*`?([a-z0-9_\-]+\.md)', txt):
        if m not in files: bad.append((f.name, m))
print("Bad citations:", bad if bad else "none")
EOF

